List<List<String>> wordBreakAll(String s, Set<String> wordDict) {
  if (s.isEmpty) return [];
  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordDict.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  List<List<String>> result = [];
  void backtrack(int index, List<String> current) {
    if (index == s.length) {
      result.add(List.from(current));
      return;
    }

    for (int j = index; j < s.length; j++) {
      if (dp[j] && wordDict.contains(s.substring(j, index))) {
        current.add(s.substring(j, index));
        backtrack(j + 1, current);
        current.removeLast();
      }
    }
  }

  backtrack(0, []);
  return result;
}

