  String pattern = "EXAMPLE";
  String text = "HERE IS A SIMPLE EXAMPLE";

  bool hasPattern(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;

    if (m > n) return false;

    List<List<bool>> dp = List.generate(n + 1, (_) => List<bool>.filled(m + 1, false));

    for (int i = 0; i <= n; i++) {
      dp[i][0] = true;
    }

    for (int j = 0; j <= m; j++) {
      dp[0][j] = true;
    }

    for (int i = 1; i <= n; i++) {
      for (int j = 1; j <= m; j++) {
        if (pattern[j - 1] == text[i - 1]) {
          dp[i][j] = dp[i - 1][j - 1];
        } else {
          dp[i][j] = dp[i - 1][j];
        }
      }
    }

    return dp[n][m];
  }

  if (hasPattern(text, pattern)) {
    print("Pattern found at positions: ${List.generate(text.length, (i) => i + 1).join(' ')}");
  } else {
    print("Pattern not found.");
  }
}

