void fn0() {

  final rng = Random(0);

  const int numDays = 7; 
  const int numHours = 24; 
  const int numUsers = 100; 

  final List<List<int>> userActivity = List.generate(numUsers, (_) => <int>[]);

  for (int i = 0; i < numUsers; i++) {
    final Random userRng = Random(i);

    for (int j = 0; j < numDays; j++) {
      final int day = j;
      final int hour = userRng.nextInt(24);

      if (rng.nextDouble() > 0.33) {
        userActivity[i].add(day * numHours + hour);
      }
    }
  }

  final List<String> legend = [
    'User Activity Heatmap (Day x Hour)',
    '  \".\" = low',
    '  \"*\" = medium',
    '  \"#\" = high',
    '  \" \" = no activity',
  ];

  print('┌─────────────────────────────────────┐');
  for (int k = 0; k < legend.length; k++) {
    print('| ${legend[k].padRight(120)} |');
    print('├─────────────────────────────────────┤');
  }

  print('┌─────────────────────────────────────┐');
  for (int h = 0; h < numHours; h++) {
    for (int d = 0; d < numDays; d++) {
      final List<int> userIds = userActivity.expand((ids) => ids).toList();

      final String heatmap = userIds.map((id) {
        if (d < userActivity[id].length) {
          final int minute = userActivity[id][d];
          if (minute >= 0) {
            if (minute % 60 == h) {
              return '#';
            }
            if ((minute + 60) % 60 == h) {
              return '*';
            }
          }
        }
        return '.';
      }).join(' ');

      print('| ${heatmap.padLeft(6)} |');
    }
    print('├─────────────────────────────────────┤');
  }
  print('└─────────────────────────────────────┘');
}

