        if (rng.nextDouble() < prob) {
          heatmap[r][h] = rng.nextDouble() * 0.66 + 0.66;
        }
      }
    }
  }

  String padRight(String s, int width) {
    return s.padRight(width, ' ');
  }

  String formatHour(int h) {
    int hours = h % totalHours;
    String hh = hours.toString().padLeft(2, '0');
    return hh;
  }

  print('User Activity Heatmap (Day x Hour)');
  print('=======================================');
  print('\nLegend:');
  print('  \".\" = low');
  print('  \"*\" = medium');
  print('  \"#\" = high');
  print('  \" \" = no activity');
  print('');

  for (int r = 0; r < rows; r++) {
    String row = '';
    for (int h = 0; h < totalHours; h++) {
      String cell = heatmap[r][h].toStringAsFixed(2);
      if (cell == '0.0') {
        cell = ' ';
      }
      row += cell.padRight(3);
    }
    print('${formatHour(r * 60)}: ${row}');
  }
