int solve(List<List<bool>> board, int depth) {
  if (depth == n) {
    return 1; 
  }

  int count = 0;
  for (int col = 0; col < n; col++) {
    if (!board[depth][col]) {
      board[depth][col] = true;
      count += solve(board, depth + 1);
      board[depth][col] = false;
    }
  }
  return count;
}

