int solveNQueens(List<List<int>> board, int n) {
  int count = 0;
  bool isSafe(List<List<int>> board, int row, int col) {
    for (int i = 0; i < row; i++) {
      if (board[i][col] == 1) return false;
    }
    return true;
  }

  bool place(List<List<int>> board, int row) {
    if (row == n) {
      count++;
      return true;
    }
    for (int col = 0; col < n; col++) {
      if (isSafe(board, row, col)) {
        board[row][col] = 1;
        if (place(board, row + 1)) return true;
        board[row][col] = 0;
      }
    }
    return false;
  }

  place(board, 0);
  return count;
}

