void fn0(List<String> args) {

  final int n;
  if (args.length != 1) {
    print('Usage: dart run script.dart <N>');
    return;
  }

  final String arg = args[0];
  final int? parsed = int.tryParse(arg);

  if (parsed == null) {
    print('Invalid input: ${arg}');
    return;
  }

  n = parsed;

  final List<List<int>> queens = List<List<int>>.generate(n, (_) => List<int>.filled(n, 0));

  int totalSolutions = 0;

  bool isSafe(List<List<int>> queens, int row, int col) {
    for (int i = 0; i < row; i++) {
      final int colI = queens[i][col];
      if (colI == 1) return false;
      if (colI == -1) return true;
      if (colI != -col) return false;
    }
    return true;
  }

  void solve(int row) {
    if (row == n) {
      totalSolutions++;
      print('Solution ${totalSolutions}:');
      for (final List<int> row in queens) {
        print(row.map((c) => c == 1 ? 'Q ' : '.').join(' '));
      }
      print('');
      return;
    }

    for (int col = 0; col < n; col++) {
      if (isSafe(queens, row, col)) {
        queens[row][col] = 1;
        solve(row + 1);
        queens[row][col] = 0;
      }
    }
  }

  print('Solving N-Queens for N=$n');
  print('');

  solve(0);

  print('Total solutions: $totalSolutions');
}

