/// Abstract class acting as an interface for quaternions.
abstract class Quaternion {
  double get real;
  double get imaginary;
  Quaternion conjugate();
  Quaternion inverse();
  Quaternion normalized();
  Quaternion sqrt();
  Quaternion pow(double exponent);
  double norm();
  Quaternion operator +(covariant Quaternion q);
  Quaternion operator -(covariant Quaternion q);
  Quaternion operator *(covariant Quaternion q);
  Quaternion operator *(double scalar);
  Quaternion operator *(covariant List<Quaternion>);
}

/// Class implementing the Quaternion interface.
class QuaternionImpl implements Quaternion {
  final double real;
  final double imaginary;

  QuaternionImpl(this.real, this.imaginary);

  @override
  Quaternion conjugate() => QuaternionImpl(real, -imaginary);

  @override
  Quaternion inverse() => QuaternionImpl(real, -imaginary) * 0.5;

  @override
  Quaternion normalized() => QuaternionImpl(
        real / norm(),
        imaginary / norm(),
      );

  @override
  Quaternion sqrt() {
    final sqrtReal = sqrt(real);
    final sqrtImaginary = sqrt(imaginary);
    return QuaternionImpl(
      (sqrtReal + real) / 2,
      (sqrtImaginary + imaginary) / 2,
    );
  }

  @override
  Quaternion pow(double exponent) {
    final exponentReal = real * exponent;
    final exponentImaginary = imaginary * exponent;
    return QuaternionImpl(
      exponentReal - (exponentImaginary * 2),
      exponentImaginary,
    );
  }

  @override
  double norm() => sqrt(real * real + imaginary * imaginary);

  @override
  Quaternion operator +(covariant Quaternion q) {
    return QuaternionImpl(
      real + q.real,
      imaginary + q.imaginary,
    );
  }

  @override
  Quaternion operator -(covariant Quaternion q) {
    return QuaternionImpl(
      real - q.real,
      imaginary - q.imaginary,
    );
  }

  @override
  Quaternion operator *(covariant Quaternion q) {
    return QuaternionImpl(
      real * q.real - imaginary * q.imaginary,
      real * q.imaginary + imaginary * q.real,
    );
  }

  @override
  Quaternion operator *(double scalar) {
    return QuaternionImpl(real * scalar, imaginary * scalar);
  }

  @override
  Quaternion operator *(covariant List<Quaternion>) {
    final result = List<Quaternion>.filled(
      q1.length,
      0.0,
    );
    for (var i = 0; i < q1.length; i++) {
      result[i] = q1[i] * q2[i];
    }
    return result;
  }
}

