/// Represents a quaternion in 4-dimensional space.
class Quaternion {
  final double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  /// Constructs a quaternion from its real and imaginary parts.
  factory Quaternion.fromList(List<double> parts) {
    return Quaternion(parts[0], parts[1], parts[2], parts[3]);
  }

  /// Constructs a quaternion from two other quaternions.
  factory Quaternion.fromQuaternions(Quaternion q1, Quaternion q2) {
    return Quaternion(
      q1.x * q2.w + q1.w * q2.x,
      q1.y * q2.w + q1.w * q2.y,
      q1.z * q2.w + q1.w * q2.z,
      q1.w * q2.w - q1.x * q2.x - q1.y * q2.y - q1.z * q2.z,
    );
  }

  /// Constructs a quaternion from a scalar and a vector.
  factory Quaternion.fromScalarAndVector(double scalar, Vector3 vector) {
    return Quaternion(scalar * vector.x, scalar * vector.y, scalar * vector.z, scalar);
  }

  /// Returns the conjugate of the quaternion.
  Quaternion get conjugate => Quaternion(x, y, z, -w);

  /// Returns the inverse of the quaternion, if it is non-zero.
  Quaternion get inverse =>
      w == 0 ? this : Quaternion(x / w, y / w, z / w, 1 / w);

  /// Returns the norm (square root of the sum of the squares) of the quaternion.
  double get norm => sqrt(x * x + y * y + z * z + w * w);

  /// Returns the normalized version of the quaternion, with a norm of 1.
  Quaternion get normalized =>
      this * inverse;

  /// Returns the sum of two quaternions.
  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  /// Returns the difference between two quaternions.
  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  /// Returns the scalar product (dot product) of two quaternions.
  double operator *(Quaternion other) =>
      x * other.x + y * other.y + z * other.z + w * other.w;

  /// Returns the cross product (vector product) of two quaternions.
  Vector3 cross(Quaternion other) =>
      Vector3(
        y * other.z - z * other.y,
        z * other.x - x * other.z,
        x * other.y - y * other.x,
      );

  /// Returns the square of the quaternion.
  Quaternion operator *(double factor) =>
      Quaternion(x * x, y * y, z * z, w * w);

  /// Returns the square root of the quaternion, if its norm is greater than 0.
  Quaternion get sqrt =>
      w == 0
          ? this
          : Quaternion(
              (x * x + y * y + z * z + w * w).isOdd
                  ? this
                  : (x * x + y * y + z * z + w * w).isEven
                      ? Quaternion(2 * x, 2 * y, 2 * z, w)
                      : Quaternion(x, y, z, w),
            );

  @override
  String toString() =>
      'Quaternion($x, $y, $z, $w)';
}

class Vector3 {
  final double x, y, z;

  Vector3(this.x, this.y, this.z);

  Vector3 operator +(Vector3 other) =>
      Vector3(x + other.x, y + other.y, z + other.z);

  Vector3 operator -(Vector3 other) =>
      Vector3(x - other.x, y - other.y, z - other.z);

  Vector3 operator *(double factor) =>
      Vector3(x * factor, y * factor, z * factor);
}

