/// Quaternion class representing a 4-dimensional unit vector in
/// 3D space with an imaginary component.
class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  /// Constructor that takes 4 double arguments representing the
  /// x, y, z, and w components of the quaternion.
  const Quaternion(this.x, this.y, this.z, this.w);

  /// Static method that creates a Quaternion from a 4-tuple of doubles.
  factory Quaternion.fromTuple(List<double> components) {
    return Quaternion(components[0], components[1], components[2], components[3]);
  }

  /// Method that calculates the norm (magnitude) of the quaternion.
  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  /// Method that normalizes the quaternion by dividing each component
  /// by the norm.
  Quaternion normalized() {
    final double norm = norm();
    if (norm == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  /// Method that calculates the conjugate of the quaternion.
  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  /// Method that calculates the inverse of the quaternion.
  Quaternion inverse() {
    final double norm = norm();
    if (norm == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(
      x / norm,
      y / norm,
      z / norm,
      -w / norm,
    );
  }

  /// Method that calculates the dot product of two quaternions.
  double dot(Quaternion other) {
    return x * other.x + y * other.y + z * other.z + w * other.w;
  }

  /// Method that calculates the cross product of two quaternions.
  Quaternion cross(Quaternion other) {
    final Quaternion q1 = this;
    final Quaternion q2 = other;
    return Quaternion(
      (q1.y * q2.z - q1.z * q2.y),
      (q1.z * q2.x - q1.x * q2.z),
      (q1.x * q2.y - q1.y * q2.x),
      q1.w * q2.w - q1.w * q2.w,
    );
  }

  /// Method that calculates the sum of two quaternions.
  Quaternion operator +(Quaternion other) {
    return Quaternion(
      x + other.x,
      y + other.y,
      z + other.z,
      w + other.w,
    );
  }

  /// Method that calculates the difference of two quaternions.
  Quaternion operator -(Quaternion other) {
    return Quaternion(
      x - other.x,
      y - other.y,
      z - other.z,
      w - other.w,
    );
  }

  /// Method that calculates the product of two quaternions.
  Quaternion operator *(Quaternion other) {
    final Quaternion q1 = this;
    final Quaternion q2 = other;
    return Quaternion(
      q1.x * q2.x - q1.w * q2.w,
      q1.x * q2.y + q1.w * q2.z,
      q1.x * q2.z - q1.w * q2.y,
      q1.x * q2.w + q1.w * q2.x,
      q1.y * q2.x - q1.w * q2.w,
      q1.y * q2.y + q1.w * q2.z,
      q1.y * q2.z - q1.w * q2.y,
      q1.y * q2.w + q1.w * q2.x,
      q1.z * q2.x - q1.w * q2.w,
      q1.z * q2.y + q1.w * q2.z,
      q1.z * q2.z - q1.w * q2.y,
      q1.z * q2.w + q1.w * q2.x,
      0,
      0,
      0,
    );
  }

  /// Method that calculates the product of a quaternion by a scalar.
  Quaternion operator *(double scalar) {
    return Quaternion(
      x * scalar,
      y * scalar,
      z * scalar,
      w * scalar,
    );
  }

  /// Method that calculates the square of the quaternion.
  Quaternion operator ^() {
    final Quaternion q1 = this;
    return Quaternion(
      q1.x * q1.x - q1.w * q1.w,
      q1.x * q1.y + q1.w * q1.z,
      q1.x * q1.z - q1.w * q1.y,
      q1.y * q1.y - q1.w * q1.w,
    );
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

