class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion._internal(this.x, this.y, this.z, this.w);

  factory Quaternion(double x, double y, double z, double w) {
    return w == 0.0 ? Quaternion._internal(x, y, z, 0.0) : Quaternion(x, y, z, w);
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(
      x + other.x,
      y + other.y,
      z + other.z,
      w + other.w,
    );
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(
      x - other.x,
      y - other.y,
      z - other.z,
      w - other.w,
    );
  }

  Quaternion operator *(double scalar) {
    return Quaternion(
      x * scalar,
      y * scalar,
      z * scalar,
      w * scalar,
    );
  }

  Quaternion operator *(Quaternion other) {
    double xx = x * x;
    double yy = y * y;
    double zz = z * z;
    double ww = w * other.w;
    double xy = x * y;
    double xz = x * z;
    double yz = y * z;
    double wx = x * w;
    double wy = y * w;
    double wz = z * w;

    return Quaternion(
      xx - zz + ww,
      xy + wz,
      xz - wy,
      xy - wz,
    );
  }

  Quaternion get conjugate {
    return Quaternion(x, y, z, -w);
  }

  double get norm {
    return x * x + y * y + z * z + w * w;
  }

  Quaternion get normalized {
    if (norm == 0.0) return Quaternion.zero;
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  static const Quaternion zero = Quaternion(0.0, 0.0, 0.0, 0.0);

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

