/// Abstract class acting as an interface for quaternions.
abstract class Quaternion {
  double get x;
  double get y;
  double get z;
  double get w;

  Quaternion operator +(Quaternion other);
  Quaternion operator -(Quaternion other);
  Quaternion operator *(double scalar);
  Quaternion operator *(Quaternion other);
  Quaternion inverse();
  Quaternion conjugate();
  double norm();
  Quaternion normalized();
}

/// Implementation of the Quaternion interface.
class QuaternionImpl implements Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  QuaternionImpl(this.x, this.y, this.z, this.w);

  @override
  double get x => x;
  @override
  double get y => y;
  @override
  double get z => z;
  @override
  double get w => w;

  @override
  Quaternion operator +(Quaternion other) =>
      QuaternionImpl(x + other.x, y + other.y, z + other.z, w + other.w);

  @override
  Quaternion operator -(Quaternion other) =>
      QuaternionImpl(x - other.x, y - other.y, z - other.z, w - other.w);

  @override
  Quaternion operator *(double scalar) =>
      QuaternionImpl(x * scalar, y * scalar, z * scalar, w * scalar);

  @override
  Quaternion operator *(Quaternion other) =>
      QuaternionImpl(
        x * other.w - y * other.z - z * other.y,
        x * other.z + y * other.w - z * other.x,
        x * other.y + y * other.w + z * other.z,
        w * other.w - x * other.x - y * other.y - z * other.z,
      );

  @override
  Quaternion inverse() {
    double denom = x * x + y * y + z * z + w * w;
    if (denom == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return QuaternionImpl(
      -x / denom,
      -y / denom,
      -z / denom,
      w / denom,
    );
  }

  @override
  Quaternion conjugate() =>
      QuaternionImpl(x, -y, z, w);

  @override
  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  @override
  Quaternion normalized() {
    double norm = norm();
    if (norm == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return QuaternionImpl(
      x / norm,
      y / norm,
      z / norm,
      w / norm,
    );
  }

  @override
  String toString() {
    return 'QuaternionImpl($x, $y, $z, $w)';
  }
}

