      Quaternion((q0 * q0 + q1 * q1 + q2 * q2 + q3 * q3)
          .absToDouble(),
        (q1 * q0 + q2 * q3) * 1 / norm,
        (q2 * q0 + q3 * q1) * 1 / norm,
        (q3 * q0 + q1 * q2) * 1 / norm);

  Quaternion get inverse => this * conjugate;

  @override
  String toString() =>
      'Quaternion(${q0.toStringAsFixed(3)}, ${q1.toStringAsFixed(3)}, ${q2.toStringAsFixed(3)}, ${q3.toStringAsFixed(3)})';
}

