class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  const Quaternion(this.x, this.y, this.z, this.w);

  /// Returns the conjugate of the quaternion.
  /// The conjugate of a quaternion `q` is defined as:
  ///   q = x + yi + jz + kw
  ///   conjugate(q) = x - yi + jz - kw
  Quaternion conjugate() => Quaternion(x, -y, -z, w);

  /// Returns the inverse of the quaternion.
  /// The inverse of a quaternion `q` is defined as:
  ///   q = x + yi + jz + kw
  ///   inverse(q) = 1 / (x^2 + y^2 + z^2 + w^2) * (q - x + yi - jz + kw)
  Quaternion inverse() {
    double det = x * x + y * y + z * z + w * w;
    if (det == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(
      (x * x + y * y + z * z + w * w) / det,
      -x / det,
      -y / det,
      -z / det,
    );
  }

  /// Returns the normalized version of the quaternion.
  /// The normalized version of a quaternion `q` is defined as:
  ///   q = x + yi + jz + kw
  ///   normalized(q) = (1 / (x^2 + y^2 + z^2 + w^2)) * q
  Quaternion normalize() {
    double norm = x * x + y * y + z * z + w * w;
    if (norm == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(
      x / norm,
      y / norm,
      z / norm,
      w / norm,
    );
  }

  /// Returns the quaternion multiplied by a scalar.
  /// `scalar` can be any double value.
  Quaternion operator * (double scalar) => Quaternion(
        x * scalar,
        y * scalar,
        z * scalar,
        w * scalar,
      );

  /// Returns the quaternion added to another quaternion.
  /// `other` can be any quaternion object.
  Quaternion operator + (Quaternion other) => Quaternion(
        x + other.x,
        y + other.y,
        z + other.z,
        w + other.w,
      );

  /// Returns the quaternion subtracted from another quaternion.
  /// `other` can be any quaternion object.
  Quaternion operator - (Quaternion other) => Quaternion(
        x - other.x,
        y - other.y,
        z - other.z,
        w - other.w,
      );

  /// Returns the quaternion multiplied by another quaternion.
  /// `other` can be any quaternion object.
  Quaternion operator * (Quaternion other) => Quaternion(
        x * other.x - y * other.y - z * other.z - w * other.w,
        x * other.y + y * other.x + z * other.w - w * other.z,
        x * other.z - y * other.w + z * other.x + w * other.y,
        x * other.w + y * other.z - z * other.y - w * other.x,
      );

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

