    print('Modulus must be greater than 1.');
    return;
  }

  BigInt? modInverse;
  BigInt? gcd = BigInt.zero;

  final BigInt m0 = m;

  while (gcd.compareTo(BigInt.zero) < 0) {
    final BigInt t = gcd;
    gcd = m % gcd;
    t = m;
    m = gcd;
    gcd = t;
  }

