Map<String, int> fn0(List<int> weights, int capacity) {
  if (weights.isEmpty) return {};
  final int n = weights.length;
  final List<Map<String, int>> dp = List.generate(n + 1, (_) => {});
  for (int i = 0; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {
      dp[i][w] = 0;
    }
  }
  for (int i = 0; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {
      if (weights[i - 1] > w) {
        dp[i][w] = dp[i - 1][w];
      } else {
        dp[i][w] = dp[i - 1][w] > dp[i][w - weights[i - 1]]
            ? dp[i - 1][w]
            : dp[i][w - weights[i - 1]];
      }
    }
  }
  final Map<String, int> result = {};
  for (int i = n; i > 0; i--) {
    if (dp[i][capacity] > dp[i - 1][capacity]) {
      result[i.toString()] = weights[i - 1];
    }
  }
  return result;
}

