    List<int> LPS = List<int>.filled(pattern.length, 0);
    int len = 0;
    int i = 1;

    while (i < pattern.length) {
      if (pattern[i] == pattern[len]) {
        len++;
        LPS[i] = len;
        i++;
      } else {
        if (len != 0) {
          len = LPS[len - 1];
        } else {
          LPS[i] = 0;
          i++;
        }
      }
    }

    return LPS;
  }

