      if (pattern[j] == text[i]) {
        i++;
        j++;
      }
      if (j == m) {
        result.add(i - j);
        j = LPS[j - 1];
      } else if (i < n && pattern[j] != text[i]) {
        if (j != 0) {
          j = LPS[j - 1];
        } else {
          i++;
        }
      }
