import 'dart:async';
import 'dart:convert';
class Role {
  String name;
  List<String> permissions;
  Role? parent;

  Role(this.name, this.permissions, [this.parent]);
}

class Resource {
  String name;
  List<String> permissions;

  Resource(this.name, this.permissions);
}

class AccessControlSystem {
  Map<String, List<String>> roles = {};
  Map<String, List<String>> resources = {};
  Map<String, int> userPermissions = {};

  void grantRole(String roleName, String resourceName) {
    if (!roles.containsKey(roleName)) {
      return;
    }
    if (!resources.containsKey(resourceName)) {
      return;
    }
    roles[roleName]!.add(resourceName);
  }

  void removeRole(String roleName, String resourceName) {
    if (!roles.containsKey(roleName)) {
      return;
    }
    if (!resources.containsKey(resourceName)) {
      return;
    }
    roles[roleName]!.remove(resourceName);
  }

  bool isAllowed(String user, String role, String resource) {
    if (!roles.containsKey(role)) {
      return false;
    }
    if (!resources.containsKey(resource)) {
      return false;
    }
    return roles[role]!.contains(resource);
  }

  void auditAccess(String user, String role, String resource, String action) {
    String timestamp = DateTime.now().toString();
    print('[$timestamp] ${user} attempted to $action $resource (Role: $role)');
  }
}

