Uint32List doubleToLE(double value) {

  int intVal = (value * 0x100000000) >> 24; 
  int intPart = (value * 0x100000000) & 0xFFFFFFFFFFFF;

  int intLE = ((intPart >> 24) & 0xFF) |
              ((intPart >> 16) & 0xFF) |
              ((intPart >> 8) & 0xFF) |
              (intPart & 0xFF);

  return [intLE];
}

Uint32List doubleToBE(double value) {

  int intVal = (value * 0x100000000) >> 24; 
  int intPart = (value * 0x100000000) & 0xFFFFFFFFFFFF;

  int intBE = ((intPart >> 24) & 0xFF) |
              ((intPart >> 16) & 0xFF) |
              ((intPart >> 8) & 0xFF) |
              (intPart & 0xFF);

  return [intBE];
}

class SystemInformation {
  final int hostPort;
  final bool isLittleEndian;

  SystemInformation._internal(this.hostPort, this.isLittleEndian);

  factory SystemInformation.getSystemInfo() {
    final int port = InternetAddress.getLocalHost().port;
    final bool isLE = (port & 1) != 0;
    return SystemInformation._internal(port, isLE);
  }
}

