class Rectangle {
  final double x;
  final double y;
  final double width;
  final double height;

  Rectangle(
      {required this.x,
      required this.y,
      required this.width,
      required this.height});

  Rectangle.square(double side)
      : this(x: side / 2, y: side / 2, width: side, height: side);

  Rectangle.fromPoints(Point p1, Point p2)
      : this(
          x: p1.x < p2.x ? p1.x : p2.x,
          y: p1.y < p2.y ? p1.y : p2.y,
          width: (p1.x - p2.x).abs(),
          height: (p1.y - p2.y).abs(),
        );

  Rectangle.centered(double centerX, double centerY, double halfWidth, double halfHeight)
      : this(
          x: centerX - halfWidth,
          y: centerY - halfHeight,
          width: halfWidth * 2,
          height: halfHeight * 2,
        );

  Rectangle.centeredPoint(Point center, double halfWidth, double halfHeight)
      : this(
          x: center.x - halfWidth,
          y: center.y - halfHeight,
          width: halfWidth * 2,
          height: halfHeight * 2,
        );

  Rectangle.dilated(Rectangle rect, double factor)
      : this(
          x: rect.x * factor,
          y: rect.y * factor,
          width: rect.width * factor,
          height: rect.height * factor,
        );

  Rectangle.contracted(Rectangle rect, double factor)
      : this(
          x: rect.x / factor,
          y: rect.y / factor,
          width: rect.width / factor,
          height: rect.height / factor,
        );

  Rectangle.union(Rectangle a, Rectangle b)
      : this(
          x: a.x < b.x ? a.x : b.x,
          y: a.y < b.y ? a.y : b.y,
          width: (a.x - b.x).abs() + (b.x - a.x).abs(),
          height: (a.y - b.y).abs() + (b.y - a.y).abs(),
        );

  Rectangle.intersection(Rectangle a, Rectangle b)
      : this(
          x: a.x > b.x ? a.x : b.x,
          y: a.y > b.y ? a.y : b.y,
          width: (a.x - b.x).abs() <= (a.width - b.width).abs()
              ? (a.x - b.x).abs()
              : (a.width - b.width).abs(),
          height: (a.y - b.y).abs() <= (a.height - b.height).abs()
              ? (a.y - b.y).abs()
              : (a.height - b.height).abs(),
        );

  Rectangle.difference(Rectangle a, Rectangle b)
      : this(
          x: a.x < b.x ? a.x : b.x,
          y: a.y < b.y ? a.y : b.y,
          width: (a.x - b.x).abs() + (b.x - a.x).abs() - (b.width - a.width).abs(),
          height: (a.y - b.y).abs() + (b.y - a.y).abs() - (b.height - a.height).abs(),
        );

  Rectangle.expand(Rectangle a, Rectangle b)
      : this(
          x: a.x < b.x ? a.x : b.x,
          y: a.y < b.y ? a.y : b.y,
          width: (a.x - b.x).abs() + b.width,
          height: (a.y - b.y).abs() + b.height,
        );

  Rectangle.fromEdges(double x1, double y1, double x2, double y2)
      : this(
          x: x1 < x2 ? x1 : x2,
          y: y1 < y2 ? y1 : y2,
          width: (x1 - x2).abs(),
          height: (y1 - y2).abs(),
        );

  Rectangle.centeredRectangle(Rectangle center, double halfWidth, double halfHeight)
      : this(
          x: center.x - halfWidth,
          y: center.y - halfHeight,
          width: halfWidth * 2,
          height: halfHeight * 2,
        );

  Rectangle.fromCircle(double centerX, double centerY, double radius)
      : this(
          x: centerX - radius,
          y: centerY - radius,
          width: 2 * radius,
          height: 2 * radius,
        );

  Rectangle.fromEllipse(double centerX, double centerY, double halfWidth, double halfHeight)
      : this(
          x: centerX - halfWidth,
          y: centerY - halfHeight,
          width: halfWidth * 2,
          height: halfHeight * 2,
        );

  Rectangle.fromEllipseCenter(double centerX, double centerY, double radius)
      : this(
          x: centerX - radius,
          y: centerY - radius,
          width: 2 * radius,
          height: 2 * radius,
        );

  Rectangle.fromDiagonal(double x1, double y1, double x2, double y2)
      : this(
          x: x1 < x2 ? x1 : x2,
          y: y1 < y2 ? y1 : y2,
          width: (x1 - x2).abs(),
          height: (y1 - y2).abs(),
        );

  Rectangle get center =>
      Rectangle.centeredRectangle(this, width / 2, height / 2);

  Rectangle get half =>
      Rectangle.centeredRectangle(this, width / 2, height / 2);

  Rectangle get diameter =>
      Rectangle.fromCircle(center.x, center.y, width / 2);

  Rectangle get perimeter =>
      Rectangle.fromDiagonal(x, y, x + width, y + height);

  Rectangle get area => width * height;

  Rectangle get bounds =>
      Rectangle.fromEdges(x, y, x + width, y + height);

  Rectangle get boundingBox =>
      Rectangle.intersection(bounds, perimeter);
}

