class Rectangle {
  final double centerX;
  final double centerY;
  final double halfWidth;
  final double halfHeight;

  Rectangle(
    this.centerX,
    this.centerY,
    this.halfWidth,
    this.halfHeight,
  );

  Rectangle.centered(double x, double y, double w, double h)
      : centerX = x,
        centerY = y,
        halfWidth = w / 2,
        halfHeight = h / 2;

  Rectangle.square(double x, double y, double side)
      : centerX = x,
        centerY = y,
        halfWidth = side / 2,
        halfHeight = side / 2;

  Rectangle.fromList(List<double> points)
      : centerX = points[0],
        centerY = points[1],
        halfWidth = points[2],
        halfHeight = points[3];

  bool contains(Point point) =>
      point.x >= centerX - halfWidth &&
      point.x <= centerX + halfWidth &&
      point.y >= centerY - halfHeight &&
      point.y <= centerY + halfHeight;

  bool contains(Rectangle other) =>
      contains(other.centerX - other.halfWidth) &&
      contains(other.centerX + other.halfWidth) &&
      contains(other.centerY - other.halfHeight) &&
      contains(other.centerY + other.halfHeight);

  Rectangle union(Rectangle other) =>
      Rectangle.centered(
        (other.centerX - other.halfWidth < centerX - halfWidth
            ? centerX - halfWidth
            : other.centerX - other.halfWidth),
        (other.centerY - other.halfHeight < centerY - halfHeight
            ? centerY - halfHeight
            : other.centerY - other.halfHeight),
        (other.halfWidth > halfWidth
            ? other.halfWidth
            : halfWidth) +
            (halfWidth > other.halfWidth
                ? halfWidth
                : other.halfWidth),
        (other.halfHeight > halfHeight
            ? other.halfHeight
            : halfHeight) +
            (halfHeight > other.halfHeight
                ? halfHeight
                : other.halfHeight),
      );

  Rectangle intersection(Rectangle other) =>
      Rectangle.centered(
        max(centerX - halfWidth, other.centerX - other.halfWidth),
        max(centerY - halfHeight, other.centerY - other.halfHeight),
        min(halfWidth, other.halfWidth),
        min(halfHeight, other.halfHeight),
      );

  Rectangle difference(Rectangle other) =>
      Rectangle.centered(
        centerX - other.halfWidth,
        centerY - other.halfHeight,
        halfWidth + other.halfWidth,
        halfHeight + other.halfHeight,
      );

  Rectangle split(Rectangle other) =>
      Rectangle.centered(
        other.centerX,
        other.centerY,
        other.halfWidth + halfWidth,
        other.halfHeight + halfHeight,
      );

  Rectangle rotated90() =>
      Rectangle.centered(centerY, centerX, halfHeight, halfWidth);

  Rectangle rotated180() =>
      Rectangle.centered(centerX, centerY, halfWidth, halfHeight);

  Rectangle rotated270() =>
      Rectangle.centered(centerX, centerY, halfWidth, halfHeight);

  Rectangle scaled(double factor) =>
      Rectangle.centered(
        centerX * factor,
        centerY * factor,
        halfWidth * factor,
        halfHeight * factor,
      );

  Rectangle mirrored(Rectangle other) =>
      Rectangle.centered(
        other.centerX - halfWidth,
        other.centerY - halfHeight,
        halfWidth,
        halfHeight,
      );

  @override
  String toString() => 'Rectangle(center: ($centerX, $centerY), halfWidth: $halfWidth, halfHeight: $halfHeight)';
}

