      centroids.add([0.0, 0.0]);
      continue;
    }
    double sumX = 0.0;
    double sumY = 0.0;
    for (final List<double> point in pointsInCluster) {
      sumX += point[0];
      sumY += point[1];
    }
    final double meanX = sumX / pointsInCluster.length;
    final double meanY = sumY / pointsInCluster.length;
    centroids.add([meanX, meanY]);
  }

  double distance(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < 2; i++) {
      final double diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  double distanceToCentroid(int index) {
    final List<double> point = points[index];
    double sum = 0.0;
    for (int i = 0; i < 2; i++) {
      final double diff = point[i] - centroids[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

