  int iterations = 0;

  while (currentCluster != null) {
    currentCluster = -1;
    iterations++;

    for (int i = 0; i < numPoints; i++) {
      final int? currentCluster = clusterAssignments[i];
      if (currentCluster == null) continue;

      for (int j = 0; j < numClusters; j++) {
        if (j == currentCluster) continue;

        final double dist = distanceToCentroid(j);
        if (dist < distanceToCentroid(currentCluster!)) {
          currentCluster = j;
        }
      }
    }

    if (currentCluster == -1) break;

    for (int i = 0; i < numPoints; i++) {
      final int? currentCluster = clusterAssignments[i];
      if (currentCluster == null) continue;
      if (currentCluster == currentCluster!) {
        continue;
      }

      final int? newCluster = currentCluster;
      clusterAssignments[i] = newCluster;
    }
